#pragma once
#include <Input/KeyDef.hpp>

#include <array>
#include <functional>

namespace RC::Input
{
    using EventCallbackCallable = std::function<void()>;
    using ModifierKeyArray = std::array<Input::ModifierKey, max_modifier_keys>;
    class Handler
    {
      public:
        using ModifierKeyArray = Input::ModifierKeyArray;
    };
} // namespace RC::Input
